/**
 * Personal API token rows. Every read is filtered by `orgId`; the secret is
 * never stored, only its digest, so `token_hash` is the only lookup key.
 */
import { and, count, desc, eq, gt, isNull, sql } from "drizzle-orm";
import { getDb, apiTokens } from "@/server/db";
import { orgPredicate } from "./base-repository";
import type { ApiTokenRow, NewApiTokenRow } from "@/server/db/schema/api-tokens";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";

/** A token is usable when it is neither revoked nor expired at `now`. */
function usablePredicate(now: IsoTimestamp) {
  return and(isNull(apiTokens.revokedAt), gt(apiTokens.expiresAt, now));
}

export async function findTokenById(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiTokenRow | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();
  return row ?? null;
}

export async function findTokenByHash(
  tokenHash: string,
): Promise<ApiTokenRow | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(eq(apiTokens.tokenHash, tokenHash))
    .get();
  return row ?? null;
}

/** Newest first; `rowid` breaks ties between tokens created in the same millisecond. */
export async function listTokensForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiTokenRow[]> {
  return getDb()
    .select()
    .from(apiTokens)
    .where(
      and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.userId, userId)),
    )
    .orderBy(desc(apiTokens.createdAt), sql`rowid DESC`)
    .all();
}

/** Every not-yet-revoked token a user holds in one org, expired ones included. */
export async function listUnrevokedTokensForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiTokenRow[]> {
  return getDb()
    .select()
    .from(apiTokens)
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .all();
}

/**
 * Inserts the row only if the user has fewer than `limit` usable tokens in the
 * org. The count and the insert share one synchronous SQLite transaction, so
 * two concurrent creates cannot both pass the check.
 */
export function insertTokenWithinLimit(
  row: NewApiTokenRow,
  limit: number,
  now: IsoTimestamp,
): boolean {
  return getDb().transaction((tx) => {
    const usable =
      tx
        .select({ value: count() })
        .from(apiTokens)
        .where(
          and(
            orgPredicate(apiTokens.orgId, row.orgId as OrgId),
            eq(apiTokens.userId, row.userId as UserId),
            usablePredicate(now),
          ),
        )
        .get()?.value ?? 0;

    if (usable >= limit) return false;

    tx.insert(apiTokens).values(row).run();
    return true;
  });
}

/** Sets `revoked_at` on a token that is not already revoked. */
export async function markTokenRevoked(
  orgId: OrgId,
  tokenId: string,
  now: IsoTimestamp,
): Promise<ApiTokenRow | null> {
  const row = getDb()
    .update(apiTokens)
    .set({ revokedAt: now, updatedAt: now })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.id, tokenId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .get();
  return row ?? null;
}

export async function touchTokenLastUsed(
  tokenId: string,
  now: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(apiTokens)
    .set({ lastUsedAt: now, updatedAt: now })
    .where(eq(apiTokens.id, tokenId))
    .run();
}
