/**
 * Personal API tokens: minting, listing, revoking, and resolving the bearer
 * secrets scripts and CI send on a member's behalf.
 *
 * Audit rows are written by `activity-service` from the `api_token.*` events
 * emitted here. A removed member's tokens are revoked by a listener on
 * `member.removed`, so the revocation is complete before `removeMember` resolves.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, subscribe, hashToken, randomToken, requireFound
 */
import { emit, subscribe } from "@/lib/event-bus";
import { randomToken, hashToken } from "@/lib/hash";
import { newId } from "@/lib/id";
import { assertCan, type PermissionResource } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { actorEnvelope, envelope, requireFound } from "./_support";
import { createApiTokenSchema, type CreateApiTokenInput } from "@/schemas/api-token";
import { toIsoTimestamp } from "@/types/common";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

/** Usable (not revoked, not expired) tokens one user may hold per organization. */
const MAX_USABLE_TOKENS_PER_USER = 5;

/** Every secret starts with this, so a presented value can be rejected cheaply. */
const SECRET_PREFIX = "tfk_";

/** Random bytes behind the secret; base64url encodes them URL-safely. */
const SECRET_BYTES = 32;

/** Leading characters of the secret kept in the clear for identification. */
const PREFIX_LENGTH = 12;

const DAY_MS = 24 * 60 * 60 * 1000;

function tokenResource(
  orgId: OrgId,
  ownerId: UserId,
  tokenId: string | null,
): PermissionResource {
  return { kind: "api_token", orgId, ownerId, tokenId };
}

/**
 * Mints a token for the actor. The secret is returned here and nowhere else;
 * only its SHA-256 digest is stored.
 */
export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);

  const resource = tokenResource(parsed.orgId, actor.userId, null);
  assertCan(actor, "api_token:create", resource);
  if (parsed.scope === "write") {
    assertCan(actor, "api_token:create_write", resource);
  }

  const now = new Date();
  const stamp = toIsoTimestamp(now);
  const secret = `${SECRET_PREFIX}${randomToken(SECRET_BYTES)}`;

  const apiToken = apiTokenRepo.insertTokenWithinLimit(
    {
      id: newId(),
      orgId: parsed.orgId,
      userId: actor.userId,
      name: parsed.name,
      scope: parsed.scope,
      tokenHash: hashToken(secret),
      prefix: secret.slice(0, PREFIX_LENGTH),
      expiresAt: toIsoTimestamp(new Date(now.getTime() + parsed.expiresInDays * DAY_MS)),
      lastUsedAt: null,
      revokedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    },
    MAX_USABLE_TOKENS_PER_USER,
    stamp,
  );

  if (apiToken === null) {
    throw new Error(
      `You can hold at most ${MAX_USABLE_TOKENS_PER_USER} usable API tokens in this organization. Revoke or wait for one to expire first.`,
    );
  }

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    ownerId: apiToken.userId,
    name: apiToken.name,
    scope: apiToken.scope,
  });

  return { token: secret, apiToken };
}

/** Tokens of `userId` (default: the actor) in the org, newest first, revoked and expired included. */
export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId?: UserId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  const owner = userId ?? actor.userId;
  assertCan(actor, "api_token:read", tokenResource(orgId, owner, null));
  return apiTokenRepo.listTokensForUser(orgId, owner);
}

/**
 * Revokes a token. Revoking an already-revoked token is a no-op that returns
 * it unchanged, so the original `revokedAt` and the audit trail are preserved.
 */
export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);

  const existing = requireFound(
    await apiTokenRepo.findTokenById(orgId, tokenId),
    "API token",
    tokenId,
  );
  assertCan(actor, "api_token:revoke", tokenResource(orgId, existing.userId, tokenId));

  if (existing.revokedAt !== null) return existing;

  const revoked = await apiTokenRepo.markTokenRevoked(
    orgId,
    tokenId,
    toIsoTimestamp(new Date()),
  );
  if (revoked === null) {
    // Another request revoked it between the read and the write; it was audited there.
    return requireFound(
      await apiTokenRepo.findTokenById(orgId, tokenId),
      "API token",
      tokenId,
    );
  }

  await emit("api_token.revoked", {
    ...actorEnvelope(actor),
    tokenId: revoked.id,
    ownerId: revoked.userId,
    name: revoked.name,
  });

  return revoked;
}

/**
 * Resolves a presented secret to the `Actor` it acts as, or `null` if it is
 * unknown, revoked, expired, or its user or organization no longer qualifies.
 * A `read` token acts as a viewer; a `write` token acts with the member's
 * current role. A successful call stamps `lastUsedAt`.
 */
export async function authenticateApiToken(token: string): Promise<Actor | null> {
  if (!token.startsWith(SECRET_PREFIX)) return null;

  const stored = await apiTokenRepo.findTokenByHash(hashToken(token));
  if (stored === null) return null;

  const now = toIsoTimestamp(new Date());
  if (stored.revokedAt !== null || stored.expiresAt <= now) return null;

  const org = await orgRepo.findOrgById(stored.orgId);
  if (org === null || org.archivedAt !== null) return null;

  const member = await memberRepo.findMember(stored.orgId, stored.userId);
  if (member === null || member.status !== "active") return null;

  await apiTokenRepo.touchTokenLastUsed(stored.id, now);

  return {
    userId: stored.userId,
    orgId: stored.orgId,
    role: stored.scope === "read" ? "viewer" : member.role,
  };
}

/**
 * Revokes every not-yet-revoked token a removed member holds in the org,
 * expired ones included, audited with the remover as actor. Other orgs are untouched.
 */
export function registerApiTokenListeners(): Unsubscribe {
  return subscribe("member.removed", async (payload) => {
    const tokens = await apiTokenRepo.listUnrevokedTokensForUser(
      payload.orgId,
      payload.userId,
    );

    for (const token of tokens) {
      const revoked = await apiTokenRepo.markTokenRevoked(
        payload.orgId,
        token.id,
        toIsoTimestamp(new Date()),
      );
      if (revoked === null) continue;

      await emit("api_token.revoked", {
        ...envelope(payload.orgId, payload.actorId),
        tokenId: revoked.id,
        ownerId: revoked.userId,
        name: revoked.name,
      });
    }
  });
}
