import { beforeAll, beforeEach, describe, expect, it } from "vitest";
import { getDb, members, activityEvents } from "@/server/db";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import * as svc from "@/server/services/api-token-service";
import * as memberSvc from "@/server/services/member-service";
import { setupTestDb, resetTestDb, seedTwoTenants } from "../helpers/db";
import { ALICE, BOB, ORG_A, ORG_B, makeActor } from "../helpers/factories";
import { newId } from "@/lib/id";
import { toIsoTimestamp } from "@/types/common";

beforeAll(async () => { await setupTestDb(); });
beforeEach(async () => {
  await resetTestDb();
  unregisterEventHandlers();
  registerEventHandlers();
});

const input = { orgId: ORG_A, name: " ci ", scope: "read" as const, expiresInDays: 30 };

describe("scratch api tokens", () => {
  it("creates, hashes, audits, caps and revokes", async () => {
    await seedTwoTenants();
    const db = getDb();
    db.insert(members).values([
      { id: newId(), orgId: ORG_A, userId: ALICE, role: "member", status: "active", createdAt: toIsoTimestamp(new Date()), updatedAt: toIsoTimestamp(new Date()) },
      { id: newId(), orgId: ORG_A, userId: BOB, role: "viewer", status: "active", createdAt: toIsoTimestamp(new Date()), updatedAt: toIsoTimestamp(new Date()) },
    ] as never).run();
    const alice = makeActor({ userId: ALICE, orgId: ORG_A, role: "member" });
    const bob = makeActor({ userId: BOB, orgId: ORG_A, role: "viewer" });

    const { token, apiToken } = await svc.createApiToken(alice, input);
    expect(token.startsWith("tfk_")).toBe(true);
    expect(apiToken.name).toBe("ci");
    expect(apiToken.prefix).toBe(token.slice(0, 12));
    expect(JSON.stringify(apiToken)).not.toContain(token);
    const raw = db.$client.prepare("select * from api_tokens").all() as any[];
    expect(JSON.stringify(raw)).not.toContain(token);
    expect(await svc.authenticateApiToken(token)).toEqual({ userId: ALICE, orgId: ORG_A, role: "viewer" });

    await expect(svc.createApiToken(bob, { ...input, scope: "write" })).rejects.toThrow();
    await expect(svc.createApiToken(alice, { ...input, name: "  " })).rejects.toThrow();
    await expect(svc.createApiToken(alice, { ...input, orgId: ORG_B })).rejects.toThrow();

    for (let i = 0; i < 4; i++) await svc.createApiToken(alice, input);
    await expect(svc.createApiToken(alice, input)).rejects.toThrow();
    expect(await svc.listApiTokens(alice, ORG_A)).toHaveLength(5);

    const revoked = await svc.revokeApiToken(alice, ORG_A, apiToken.id);
    expect(revoked.revokedAt).not.toBeNull();
    const again = await svc.revokeApiToken(alice, ORG_A, apiToken.id);
    expect(again.revokedAt).toBe(revoked.revokedAt);
    expect(await svc.authenticateApiToken(token)).toBeNull();
    await svc.createApiToken(alice, input);

    const audit = db.select().from(activityEvents).all().filter((r) => r.action.startsWith("api_token."));
    expect(audit.filter((r) => r.action === "api_token.created")).toHaveLength(6);
    expect(audit.filter((r) => r.action === "api_token.revoked")).toHaveLength(1);
    expect(JSON.stringify(audit)).not.toContain(token.slice(0, 12) + token.slice(12, 20));
  });

  it("revokes on member removal and expires at exact expiry", async () => {
    await seedTwoTenants();
    const db = getDb();
    const now = toIsoTimestamp(new Date());
    db.insert(members).values([
      { id: "01HZZZMEMBER0000000000001", orgId: ORG_A, userId: BOB, role: "admin", status: "active", createdAt: now, updatedAt: now },
      { id: "01HZZZOWNER00000000000001", orgId: ORG_A, userId: ALICE, role: "owner", status: "active", createdAt: now, updatedAt: now },
    ] as never).run();
    const owner = makeActor({ userId: ALICE, orgId: ORG_A, role: "owner" });
    const bobAct = makeActor({ userId: BOB, orgId: ORG_A, role: "admin" });
    const { token } = await svc.createApiToken(bobAct, { ...input, scope: "write" });
    expect(await svc.authenticateApiToken(token)).toEqual({ userId: BOB, orgId: ORG_A, role: "admin" });
    await memberSvc.removeMember(owner, { orgId: ORG_A, memberId: "01HZZZMEMBER0000000000001" as never });
    expect(await svc.authenticateApiToken(token)).toBeNull();
    const audit = db.select().from(activityEvents).all().filter((r) => r.action === "api_token.revoked");
    expect(audit).toHaveLength(1);
    expect(audit[0].actorId).toBe(ALICE);
  });
});
